(() => {
'use strict';
const $=s=>document.querySelector(s),phone=window.libphonenumber,catalog=window.SANTA_NAME_AUDIO,player=$('#call-player'),status=$('#call-demo-status'),service=$('#call-service-status');
let helper=null,prepared=null,job=0,stage='idle',urls=[],endpoint='',liveReady=false,requiresCode=false,poll=null;
const loadHelper=()=>helper?Promise.resolve(helper):import('./call-audio.mjs').then(m=>(helper=m));
const names=[...new Set(catalog.flatMap(n=>[n.name,...n.aliases||[]]))].sort((a,b)=>a.localeCompare(b,'es'));for(const name of names)$('#call-names').append(new Option(name,name));
const countries=phone.getCountries(),display=new Intl.DisplayNames(['es'],{type:'region'});countries.sort((a,b)=>display.of(a).localeCompare(display.of(b),'es'));for(const country of countries)$('#call-country').append(new Option(`${display.of(country)} (+${phone.getCountryCallingCode(country)})`,country));$('#call-country').value='PE';
const inputName=()=>$('#call-name').value.trim().normalize('NFC');
function stop(clear=true){++job;stage='idle';$('#call-preview-title').textContent='Escucha cómo será la llamada';player.pause();player.removeAttribute('src');player.hidden=true;$('#call-keypad').hidden=true;$('#call-stop').hidden=true;$('#call-demo').disabled=false;if(clear){prepared=null;for(const u of urls)URL.revokeObjectURL(u);urls=[];}}
function invalidate(){stop();status.textContent='Prepara una nueva prueba con el nombre y el saludo elegidos.';}
async function lookup(){const value=inputName(),m=await loadHelper(),name=m.findName(catalog,value);if(value!==inputName())return;$('#call-name-status').textContent=name?`Voz disponible para ${name.name}. Se pronunciará únicamente ese nombre después de «Hola».`:value?'No encontramos una grabación exacta. Elige un nombre de las sugerencias.':'Elige uno de los nombres grabados con la voz de Santa.';}
$('#call-name').addEventListener('input',()=>{invalidate();lookup();});$('#call-profile').addEventListener('change',invalidate);
function parsePhone(){const value=$('#call-phone').value.trim(),country=$('#call-country').value;try{const parsed=phone.parsePhoneNumberFromString(value,country);return parsed?.isValid()?parsed:null;}catch{return null;}}
function numberState(){const p=parsePhone();$('#call-number-status').textContent=p?`Número preparado: ${p.formatInternational()}`:$('#call-phone').value.trim()?'Revisa la cantidad de dígitos y el país seleccionado.':'Selecciona el país y escribe el número sin el código internacional.';}
$('#call-phone').addEventListener('input',numberState);$('#call-country').addEventListener('change',numberState);
async function prepare(){const m=await loadHelper(),recording=m.findName(catalog,inputName());if(!recording){$('#call-name').focus();throw new Error('Elige un nombre que tenga una grabación disponible.');}return m.prepareCall(recording,$('#call-profile').value,document.baseURI);}
$('#call-demo').addEventListener('click',async()=>{stop();const id=job;$('#call-demo').disabled=true;status.textContent='Preparando la bienvenida del duende y el saludo de Santa…';try{const call=await prepare();if(id!==job)return;prepared=call;urls=[URL.createObjectURL(new Blob([call.intro],{type:'audio/wav'})),URL.createObjectURL(new Blob([call.santa],{type:'audio/wav'}))];player.src=urls[0];player.hidden=false;$('#call-stop').hidden=false;$('#call-keypad').hidden=false;stage='intro';status.textContent='Prueba local: escucha al duende y presiona 1 para aceptar. No se está marcando ningún teléfono.';try{await player.play();}catch{status.textContent='Toca reproducir para escuchar al duende. Luego presiona 1 para aceptar esta prueba.';}}catch(e){if(id===job){stop();status.textContent=e.message;}}});
function accept(){if(!prepared||!['intro','waiting'].includes(stage))return;player.pause();player.src=urls[1];stage='santa';$('#call-keypad').hidden=true;$('#call-preview-title').textContent='Santa tiene un mensaje para '+inputName();status.textContent=`Santa te saluda. «${inputName()}» se pronuncia después de «Hola», con la música del saludo elegido.`;player.play().catch(()=>{status.textContent='Toca reproducir para escuchar el saludo preparado.';});}
$('#call-accept').addEventListener('click',accept);document.addEventListener('keydown',e=>{if(e.key==='1'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!$('#llamadas').hidden){e.preventDefault();accept();}});
player.addEventListener('ended',()=>{if(stage==='intro'){stage='waiting';status.textContent='El duende espera tu respuesta. Presiona 1 para escuchar a Santa.';}else if(stage==='santa'){stage='done';$('#call-demo').disabled=false;status.textContent='La prueba ha terminado. Puedes escuchar otro saludo o preparar otra llamada.';}});
$('#call-stop').addEventListener('click',()=>{stop();status.textContent='Prueba finalizada.';});window.addEventListener('aldea:navigate',()=>{if($('#llamadas').hidden)stop();});
async function serviceState(){try{endpoint=String(window.SANTA_CALLS_CONFIG?.endpoint||'').replace(/\/$/,'');if(!endpoint)return;const u=new URL(endpoint);if(u.protocol!=='https:')return;const r=await fetch(endpoint+'/ready',{signal:AbortSignal.timeout(8000)}),v=await r.json();liveReady=r.ok&&v.enabled===true;requiresCode=v.requiresAccessCode===true;$('#call-code-label').hidden=!requiresCode;service.textContent=liveReady?'Servicio telefónico disponible. Completa los datos para solicitar la llamada.':'Llamadas al celular: pendientes de activación. La prueba de audio está disponible.';}catch{service.textContent='No se pudo comprobar el servicio telefónico. La prueba de audio sigue disponible.';}}
$('#call-form').addEventListener('submit',async e=>{e.preventDefault();if(!liveReady){service.textContent='El servicio telefónico aún no está activado. Puedes escuchar la prueba personalizada; no se ha marcado ningún número.';return;}const m=await loadHelper(),name=m.findName(catalog,inputName()),number=parsePhone();if(!name){service.textContent='Elige un nombre con grabación disponible.';return;}if(!number){$('#call-phone').focus();service.textContent='Escribe un número válido con su país.';return;}if(!$('#call-consent').checked){service.textContent='Confirma que tienes autorización para llamar a este número.';return;}const code=$('#call-code').value;if(requiresCode&&!code){$('#call-code').focus();service.textContent='Introduce tu código de llamada.';return;}$('#call-live').disabled=true;service.textContent='Solicitando la llamada al servicio telefónico…';try{const r=await fetch(endpoint+'/calls',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+code},body:JSON.stringify({name:inputName(),to:number.number,profile:$('#call-profile').value,consent:true}),signal:AbortSignal.timeout(20000)}),v=await r.json();if(!r.ok)throw new Error(v.error||'El servicio no pudo aceptar la llamada.');service.textContent='Solicitud aceptada por el operador. Espera la llamada en el número indicado; presiona 1 para escuchar a Santa.';let attempts=0;clearInterval(poll);poll=setInterval(async()=>{if(++attempts>60){clearInterval(poll);$('#call-live').disabled=false;return;}try{const rr=await fetch(endpoint+'/calls/'+encodeURIComponent(v.id),{headers:{Authorization:'Bearer '+code}}),state=await rr.json();const labels={pending:'Esperando confirmación del operador. Evita solicitar otra llamada mientras se comprueba.',queued:'La llamada está en cola.',initiated:'El operador está iniciando la llamada.',ringing:'El teléfono está sonando.',answered:'La llamada fue atendida. Escucha al duende.',accepted:'Se recibió la tecla 1. Santa está hablando.',completed:'La llamada ha finalizado.',busy:'El número está ocupado.',failed:'La llamada no se pudo completar.','no-answer':'El número no respondió.',canceled:'La llamada fue cancelada.'};if(rr.ok)service.textContent=labels[state.status]||'El operador está procesando la llamada.';if(['completed','busy','failed','no-answer','canceled'].includes(state.status)){clearInterval(poll);$('#call-live').disabled=false;}}catch{}},3000);}catch(e){$('#call-live').disabled=false;service.textContent=e.message||'No se pudo solicitar la llamada.';}});
serviceState();
})();
